for row in imported_data_sheet.iter_rows(min_col=5, max_col=5):
    cell = row[0]
    if cell.value is not None:
        try:
            date = datetime.strptime(cell.value, '%Y-%m-%d %H:%M:%S').date()
            if max_date is None or date > max_date:
