from openpyxl import load_workbook
from openpyxl.styles import Alignment, Font
import re

def process_sheet(wb, sheet_name='Sheet1'):
    wb = load_workbook('input.xlsx')
    sheet = wb[sheet_name]

    # Ensure Excel is set to Automatic Calculation
    # This is a workaround since openpyxl doesn't directly control Excel's calculation mode
    # We assume the workbook is already set to Automatic Calculation

    # Convert any text-stored formulas back to formulas
    for row in sheet.iter_rows():
        for cell in row:
            if cell.data_type == 'f' and cell.value is None:
                # If the cell is a formula but evaluates to None, we can leave it as is
                continue
            if cell.data_type == 's' and re.match(r'=\w+', cell.value):
                # If the cell contains a formula as text, convert it to a formula
                cell.value = cell.value
                cell.data_type = 'f'

    # Set calculation mode to automatic (this is a workaround)
    # Note: openpyxl does not support changing calculation mode directly

    # Round numbers in columns D, E, F to one decimal place
    for row in sheet.iter_rows(min_col=4, max_col=6):
        for cell in row:
            if cell.data_type == 'n':
                cell.value = round(cell.value, 1)

    # Apply number formatting to columns D, E, F
    for cell in sheet['D'] + sheet['E'] + sheet['F']:
        if cell.data_type == 'n':
            cell.number_format = '0.0'

    # Identify blocks of data separated by blank rows
    blocks = []
    current_block = []
    for row in sheet.iter_rows(min_row=1, max_row=sheet.max_row):
        if row[0].value is None:
            if current_block:
                blocks.append(current_block)
                current_block = []
        else:
            current_block.append(row)
    if current_block:
        blocks.append(current_block)

    # Sort each block by column D in descending order
    for block in blocks:
        # Extract rows in the block
        block_rows = [row for row in block]
        # Extract the data for sorting
        data = [(row[3].value, row) for row in block_rows]
        # Sort by column D (index 3) in descending order
        data.sort(reverse=True, key=lambda x: x[0])
        # Reorder the rows in the block
        for i, (d_value, row) in enumerate(data):
            for j, cell in enumerate(row):
                sheet.cell(row=block[0][0].row + i, column=cell.column, value=cell.value)

    # Ensure columns D, E, F are bold and center-aligned
    for col in ['D', 'E', 'F']:
        for cell in sheet[col]:
            if cell.data_type == 'n':
                cell.font = Font(bold=True)
                cell.alignment = Alignment(horizontal='center')

    # Save the workbook
    wb.save('output.xlsx')

process_sheet(None)
