from openpyxl import load_workbook

# Load the workbook and select the active sheet
wb = load_workbook('input.xlsx')
ws = wb.active

# Extract the scores from rows 5 to 7 (B to E)
scores = []
for row in ws.iter_rows(min_row=5, max_row=7, min_col=2, max_col=5):
    scores.append([cell.value for cell in row])

# Flatten the scores into a single list of tuples (person, score)
# We'll use the row number (5, 6, 7) as the person identifier
flat_scores = []
for i, row in enumerate(scores, start=5):
    for score in row:
        flat_scores.append((i, score))

# Group scores by person
from collections import defaultdict
person_scores = defaultdict(list)
for person, score in flat_scores:
    person_scores[person].append(score)

# Calculate total scores for each person
total_scores = {person: sum(scores) for person, scores in person_scores.items()}

# Find the highest total score
max_score = max(total_scores.values())

# Determine how many people have the max score
max_people = [person for person, score in total_scores.items() if score == max_score]

# Assign points based on the number of people with the max score
points = {}
if len(max_people) == 1:
    points[max_people[0]] = 6
elif len(max_people) == 2:
    for person in max_people:
        points[person] = 3
elif len(max_people) == 3:
    for person in max_people:
        points[person] = 2
else:
    # This case shouldn't happen as we're only considering rows 5, 6, 7
    pass

# Assign 0 points to others
for person in person_scores:
    if person not in points:
        points[person] = 0

# Write the computed points to the range B5:E7
for row_idx, person in enumerate([5, 6, 7], start=1):
    for col_idx, col in enumerate(['B', 'C', 'D', 'E'], start=1):
        if col_idx - 1 == (person - 5):
            ws[f"{col}{row_idx}"] = points[person]

# Save the workbook
wb.save('output.xlsx')
