    for cell in row:
        if cell.value == lookup_value:
            col_index = cell.column
            break

# Define the range to search (from row 2 to row 10, columns B to G)
results = []
for row in ws.iter_rows(min_row=2, max_row=10):
    if row[col_index - 1].value == lookup_value:
        for cell in row[1:]:  # Skip the first column (lookup value)
            if cell.value > 0:
                results.append(cell.value)

# Write the results to B9:B10
